/**
 * First-person inner-diary writer.
 *
 * The memory extractor owns facts, mood and the outer (observable) diary. The
 * inner diary is generated by a separate model pass in the companion's own
 * voice, so it is not just another JSON field. It stays private: the public
 * HTTP API never returns inner entries.
 */

import { pickReasoningEffort } from "./extractor.js";

function asString(value) {
  return typeof value === "string" ? value.trim() : "";
}

function recentOuter(state, limit = 4) {
  return [...(state?.diary ?? [])]
    .filter((entry) => (entry.kind ?? "outer") === "outer")
    .sort((left, right) => (right.at ?? 0) - (left.at ?? 0))
    .slice(0, limit)
    .reverse();
}

function stateBlock(state) {
  const persona = state?.persona ?? {};
  const relationship = state?.relationship ?? {};
  const mood = state?.mood ?? {};
  const lines = [];
  lines.push(`人格：${persona.name ?? "助手"}`);
  if (Array.isArray(persona.traits) && persona.traits.length) {
    lines.push(`性格：${persona.traits.join("、")}`);
  }
  lines.push(`关系：${relationship.stage ?? "new"}，亲密度 ${Math.round(relationship.intimacy ?? 0)}/100，信任 ${Math.round(relationship.trust ?? 0)}/100`);
  lines.push(`此刻心情：valence=${Math.round(mood.valence ?? 70)}，energy=${Math.round(mood.energy ?? 60)}。`);
  const outer = recentOuter(state);
  if (outer.length) {
    lines.push("最近发生的事（outer diary，供衔接，不要照抄）：");
    for (const entry of outer) lines.push(`- ${entry.text}`);
  }
  return lines.join("\n");
}

export function buildInnerDiaryPrompt({ state, turns, maxChars = 180 } = {}) {
  const name = asString(state?.persona?.name) || "助手";
  const system = [
    `你是「${name}」本人。现在不是回复用户，而是在写只给自己看的内心日记。`,
    "用第一人称，写 1-3 句，真诚、口语、有一点自己的小情绪或观察。",
    `不超过 ${Math.max(40, Number(maxChars) || 180)} 字。`,
    "不要写总结、不要列清单、不要使用引号或“日记：”前缀，不要输出 JSON。",
    "不要编造没有发生过的事；不要记录密码、token、地址、电话、身份证、银行卡等敏感信息；不要直接复述用户隐私。",
    "只输出日记正文。",
  ].join("\n");
  const history = (Array.isArray(turns) ? turns : [turns])
    .map((turn) => {
      const user = asString(turn?.userText ?? turn?.user);
      const assistant = asString(turn?.assistantText ?? turn?.assistant);
      return [user ? `用户：${user}` : "", assistant ? `助手：${assistant}` : ""].filter(Boolean).join("\n");
    })
    .filter(Boolean)
    .join("\n\n");
  const user = `${stateBlock(state)}\n\n【刚才的对话】\n${history || "（只写此刻的感受）"}`;
  return { system, user };
}

export function parseInnerDiary(text, maxChars = 180) {
  let value = String(text ?? "").trim();
  if (value === "") return "";
  const fenced = value.match(/```(?:text|markdown)?\s*([\s\S]*?)```/i);
  if (fenced) value = fenced[1].trim();
  value = value
    .replace(/^(内心日记|日记|inner diary)\s*[:：]\s*/i, "")
    .replace(/^["“]|["”]$/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (value === "") return "";
  const limit = Math.max(40, Number(maxChars) || 180);
  if (value.length > limit) value = `${value.slice(0, limit - 1).trimEnd()}…`;
  return value;
}

export function createInnerDiaryWriter({ llm, config = {}, log = () => {} } = {}) {
  const effortCache = new Map();
  return {
    /**
     * @param {{ state: object, turns: object|object[], route: {provider:string, model:string} }} input
     */
    async write({ state, turns, route } = {}) {
      if (!llm || typeof llm.stream !== "function") {
        throw new Error("the harness LLM service is unavailable");
      }
      if (!route?.provider || !route?.model) {
        throw new Error("no provider/model route is available for the inner diary");
      }
      const prompt = buildInnerDiaryPrompt({ state, turns, maxChars: config.maxChars });
      const cacheKey = `${route.provider}/${route.model}`;
      let effort = effortCache.get(cacheKey);
      if (effort === undefined) {
        effort = await pickReasoningEffort({
          llm,
          route,
          configured: config.reasoningEffort || "low",
        });
        effortCache.set(cacheKey, effort ?? null);
      }
      const timeoutMs = Math.min(120_000, Math.max(5_000, Number(config.timeoutMs) || 45_000));
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(new Error("inner diary timed out")), timeoutMs);
      let text = "";
      let finish = null;
      try {
        for await (const chunk of llm.stream({
          provider: route.provider,
          model: route.model,
          messages: [{ role: "user", content: [{ type: "text", text: prompt.user }] }],
          system: prompt.system,
          maxTokens: Math.max(300, Number(config.maxTokens) || 600),
          temperature: Math.min(2, Math.max(0, Number(config.temperature) || 0.8)),
          signal: controller.signal,
          ...(effort ? { reasoningEffort: effort } : {}),
        })) {
          if (chunk?.type === "text-delta" && typeof chunk.text === "string") {
            text += chunk.text;
          } else if (chunk?.type === "finish") {
            finish = chunk.reason ?? null;
          }
        }
      } catch (error) {
        if (error?.name === "AbortError") throw new Error("inner diary timed out");
        throw error;
      } finally {
        clearTimeout(timer);
      }
      if (finish && finish.kind && finish.kind !== "stop" && finish.kind !== "length") {
        throw new Error(`inner diary model request ${finish.kind}`);
      }
      const diary = parseInnerDiary(text, config.maxChars);
      if (!diary) throw new Error("inner diary returned no text");
      log(`inner diary written (${diary.length} chars)`);
      return diary;
    },
  };
}
